                // filterItem \u5305\u542B: {name, id, key}\r
                // key \u662F\u7B5B\u9009\u7C7B\u578B\uFF08\u5982 'year', 'area', 'sort'\uFF09\r
                // id \u662F\u9009\u4E2D\u7684\u503C\r
